def parse(infile, outfile):
    # dtype = [("f0", "|U30"), ("f1", "<f8"), ("f2", "<f8")]
    # par_file_load = np.genfromtxt(par_file_name, dtype=dtype, encoding="utf-8")
    enc = guess_text_encoding(infile)

    with open(infile, "r", encoding=enc) as f:
        line_counter = 0
        work_pars = []

        for line in f.readlines():
            line_counter += 1
            trim = line.strip()
            if trim.startswith("#") or trim.strip().startswith("//") or len(trim) == 0:
                continue
            else:
                for tp in allowed_endings:

                    if trim.find("." + tp) > -1 or trim.find("." + tp.upper()) > -1:
                        print(f"woring with {tp} -> {trim}")

                        trim_a = trim.replace("." + tp, "__" + tp)
                        trim_u = trim_a.replace("." + tp.upper(), "__" + tp)

                        if trim_u.startswith("V__"):
                            trim_u = trim_u.replace("V__", "v__", 1)
                        if trim_u.startswith("A__"):
                            trim_u = trim_u.replace("A__", "v__", 1)
                        if trim_u.startswith("R__"):
                            trim_u = trim_u.replace("R__", "v__", 1)

                        if trim_u.find("()") > -1:
                            trim_u = trim_u.replace("()", "")

                        paramlist = (
                            list(FileEdit.bsnManipulator.parInfo.keys())
                            + list(FileEdit.gwManipulator.parInfo.keys())
                            + list(FileEdit.mgtManipulator.parInfo.keys())
                            + list(FileEdit.subManipulator.parInfo.keys())
                            + list(FileEdit.hruManipulator.parInfo.keys())
                            + list(FileEdit.solManipulator.parInfo.keys())
                            + list(FileEdit.rteManipulator.parInfo.keys())
                        )

                        try:
                            field_list = trim_u.split(" ")[0].strip().split("__")
                            how = field_list[0]
                            param_field = field_list[1]
                            manip_ext = field_list[2]
                            if len(field_list) > 3:
                                hydrp = field_list[3]
                            if len(field_list) > 4:
                                soltext = field_list[4]
                            if len(field_list) > 5:
                                landuse = field_list[5]
                            if len(field_list) > 6:
                                subbsn = field_list[6]
                            if len(field_list) > 7:
                                slope = field_list[7]

                            if not how in ["v", "a", "r"]:
                                print(
                                    f"error, line {line_counter} not correct modifier {how} not in ['v', 'a', 'r']"
                                )
                                continue
                            if not param_field in paramlist:
                                print(
                                    f"error, line {line_counter} param_field {param_field} not known"
                                )
                                continue
                            if not manip_ext in allowed_endings:
                                print(
                                    f"error, line {line_counter} file type {manip_ext} not in {allowed_endings}"
                                )
                                continue

                            already_used_params = [t[0] for t in work_pars]

                            if not param_field in already_used_params:
                                work_pars.append((param_field, trim_u))
                            else:
                                print(
                                    f"error, line {line_counter} param field {param_field} already used before"
                                )
                                continue
                        except Exception as e:
                            print("error parsing")
                            print(trim_u)
                            print(repr(e))
                    else:
                        continue
                # print(trim)
                # print(trim_u)
        for t in work_pars:
            print(t)
        with open(outfile, "w", encoding=enc) as outf:
            for t in work_pars:
                outf.write(t[1] + "\n")

def main(argv):
    infile = ""
    outfile = ""
    try:
        opts, args = getopt.getopt(argv, "hi:o:", ["infile=", "outfile="])
    except getopt.GetoptError:
        print("test.py -i <infile> -o <outfile>")
        sys.exit(2)
    for opt, arg in opts:
        if opt == "-h":
            print("test.py -i <infile> -o <outfile>")
            sys.exit()
        elif opt in ("-i", "--infile"):
            infile = arg

        elif opt in ("-o", "--outfile"):
            outfile = arg

    print("Infile is " + infile)
    print("Outfile is " + outfile)

    parse(infile, outfile)

def model_callib(model, mpath, param_file, sampler, repetitions, parallel):

    target_dir = f"/tmp/callib_{model}_{sampler}_{uuid.uuid4()}"
    # target_dir = os.path.join(os.getcwd(), f"callib_{model}_{sampler}_{uuid.uuid4()}")

    model4 = SimManage.SwatModel.initFromTxtInOut(
        txtInOut=mpath,
        copy=True,
        target_dir=os.path.join(target_dir, "TxtInOut"),
        force=False,
    )
    temp_dir = target_dir

    obs_filename = os.path.join("observed", "pori_flow_monthly_2003-2010.txt")
    f = open(obs_filename, "r")
    lines = f.readlines()
    f.close()
    measured = []
    for i in lines:
        measured.append(i.split(";")[2].strip())

    obs = np.array([float(i) for i in measured])

    obs_masked = np.ma.masked_where(obs == -9999.0, obs)

    par_file_name = param_file
    logger.info(f"loading parameter file {par_file_name}")

    dtype = [("f0", "|U30"), ("f1", "<f8"), ("f2", "<f8")]
    par_file_load = np.genfromtxt(par_file_name, dtype=dtype, encoding="utf-8")

    model4.swat_exec = swat_bin
    spot_setup = swat_callib_setup(
        model4, obs_masked, par_file_load, parallel=parallel, temp_dir=temp_dir
    )

    dbformat = "csv"

    kwargs = {
        "spot_setup": spot_setup,
        "parallel": parallel,
        "dbname": f"{model}_{sampler}_{repetitions}_pid{os.getpid()}",
        "dbformat": dbformat,
    }
    spot_sampler = None

    if sampler == "LHS":
        spot_sampler = spotpy.algorithms.lhs(**kwargs)

    if sampler == "MC":
        spot_sampler = spotpy.algorithms.mc(**kwargs)

    if sampler == "ROPE":
        spot_sampler = spotpy.algorithms.rope(**kwargs)

    if sampler == "MCMC":
        spot_sampler = spotpy.algorithms.mcmc(**kwargs)

    if sampler == "SA":
        spot_sampler = spotpy.algorithms.sa(**kwargs)

    if sampler == "MLE":
        spot_sampler = spotpy.algorithms.mle(**kwargs)

    if sampler == "DEMCZ":
        spot_sampler = spotpy.algorithms.demcz(**kwargs)

    if sampler == "SCEUA":
        spot_sampler = spotpy.algorithms.sceua(**kwargs)

    if sampler == "ABC":
        spot_sampler = spotpy.algorithms.abc(**kwargs)

    if sampler == "FSCABC":
        spot_sampler = spotpy.algorithms.fscabc(**kwargs)

    if sampler == "DREAM":
        spot_sampler = spotpy.algorithms.dream(**kwargs)

    if sampler == "FAST":
        spot_sampler = spotpy.algorithms.fast(**kwargs)

    spot_sampler.sample(repetitions)

    try:
        shutil.rmtree(target_dir)
    except Exception as e:
        logger.info(
            f"error removing old calibration workdir: {str(target_dir)} | {repr(e)}"
        )

    # this might break in mpi parallel mode
    if parallel == "seq":
        callib_results = spot_sampler.getdata()

        if not sampler == "FAST":
            logger.info(spotpy.analyser.get_best_parameterset(callib_results))

def main(argv):
    my_pid = os.getpid()
    model = ""
    sampler = ""
    repetitions = 0
    parallel = "seq"
    try:
        opts, args = getopt.getopt(
            argv, "hm:s:r:p:", ["model=", "sample=", "reps=", "parallel="]
        )
        logger.info(f"opts {opts} args ({args})")
    except getopt.GetoptError:
        logger.info("test.py -m <model> -s <sampler> -r <reps> -p <parallel>")
        sys.exit(2)
    for opt, arg in opts:
        if opt == "-h":
            logger.info("test.py -m <model> -s <sampler> -r <reps> -p <parallel>")
            sys.exit()
        elif opt in ("-m", "--model"):
            model = arg
            if not model in models:
                logger.info(f"{model} not in models, abort ({models})")
                sys.exit()
        elif opt in ("-s", "--sampler"):
            sampler = arg
            if not sampler in all_algorithms:
                logger.info(f"{sampler} not in models, abort ({all_algorithms})")
                sys.exit()
        elif opt in ("-r", "--reps"):
            repetitions = int(arg)
            if repetitions <= 0:
                logger.info(f"invalid number of repetitions ({repetitions}), abort")
                sys.exit()
        elif opt in ("-p", "--parallel"):
            if arg in ["seq", "mpi"]:
                parallel = arg
                if parallel == "mpi":
                    try:
                        import mpi4py
                    except ImportError:
                        logger.info(
                            f"mpi4py can't imported but is needed for ({parallel}), abort"
                        )
                        sys.exit()
                    if not sampler in parallel_samplers:
                        logger.info(
                            f"{sampler} not parallelizable, abort ({parallel_samplers})"
                        )
                        sys.exit()
            else:
                logger.info(f"{arg} not seq or mpi, abort")
                sys.exit()

    fh = logging.FileHandler(f"{model}_{sampler}_{repetitions}_{my_pid}_output.log")
    fh.setFormatter(formatter)
    logger.addHandler(fh)

    logger.info("Model is " + model)
    logger.info("Sampler is " + sampler)
    logger.info("Repetitions is " + str(repetitions))
    logger.info("Parallel is " + parallel)

    mpath = os.path.join(os.getcwd(), os.path.join(model, config[model]["path"]))
    logger.info(f"model init path is: {mpath}")

    param_file = os.path.join(
        os.getcwd(), os.path.join("params", model + "_par_inf_spotpy.txt")
    )
    # update_SLSOIL(os.path.join(model, config[model]["path"]))
    # update_LAT_TTIME(os.path.join(model, config[model]["path"]))

    model_callib(
        model=model,
        mpath=mpath,
        param_file=param_file,
        sampler=sampler,
        repetitions=repetitions,
        parallel=parallel,
    )
